:root {
  --glass-filter: blur(18px) saturate(140%) brightness(0.7);
}

@layer base {
  :root {
    interpolate-size: allow-keywords;
    font-family: var(--font-body);
    color: var(--color-ink);
    background: var(--color-canvas);
    color-scheme: dark;
    font-synthesis: none;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  * {
    box-sizing: border-box;
  }
  html,
  body,
  #root {
    height: 100%;
  }
  body {
    margin: 0;
    min-width: 320px;
    min-height: 100vh;
    overflow: hidden;
  }
  button,
  input {
    font: inherit;
  }
  button {
    color: inherit;
    padding: 0;
  }
  /* Under the utilities layer, so a caller's border or fill always wins. */
  .ui-button {
    border: 0;
    background: none;
  }
}

@media (max-width: 1120px) {
  :root {
    --spacing-sidebar: 220px;
  }
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
a:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

